import sys,json,os,hashlib
from pathlib import Path
r=Path(sys.argv[1]);role=sys.argv[2];files=[]
for p in (r/'state').rglob('*'):
 if p.is_file():
  st=p.stat();item={'path':str(p.relative_to(r)),'bytes':st.st_size,'allocated':st.st_blocks*512}
  if p.suffix=='.json' and st.st_size<1024**2:
   try:item['json']=json.loads(p.read_text())
   except (UnicodeError,ValueError):pass
  files.append(item)
print(json.dumps({'role':role,'state_files':files},indent=2))
